function compute(state) {
  var w = state.p.map(function (x) { return Math.max(0, Number(x) || 0); });
  var n = w.length;
  var raw = w.reduce(function (a, b) { return a + b; }, 0);
  var p = w.map(function (x) { return raw > 0 ? x / raw : NaN; });
  var surprise = p.map(function (q) { return q > 0 ? -Math.log2(q) : Infinity; });
  var contrib = p.map(function (q) { return q > 0 ? -q * Math.log2(q) : (q === 0 ? 0 : NaN); });
  var H = contrib.reduce(function (a, b) { return a + b; }, 0);
  var sumP = p.reduce(function (a, b) { return a + b; }, 0);
  var labels = p.map(function (_, i) { return 'x' + (i + 1); });
  var rows = p.map(function (q, i) { return [labels[i], w[i], q, q > 0 ? surprise[i] : '∞ (never occurs)', contrib[i]]; });
  rows.push(['Σ', raw, sumP, '', H]);
  var ns = [], logn = [];
  for (var k = 1; k <= 8; k++) { ns.push(k); logn.push(Math.log2(k)); }
  return {
    values: { H: H, H_max: Math.log2(Math.max(1, n)), sum_p: sumP, raw_sum: raw, n: n },
    series: { p: p, contrib: contrib, labels: labels, ns: ns, logn: logn },
    tables: { contrib: { cols: ['Outcome', 'Weight', 'p<sub>i</sub>', '−log<sub>2</sub> p<sub>i</sub> (bits)', '−p<sub>i</sub> log<sub>2</sub> p<sub>i</sub> (bits)'], rows: rows } }
  };
}
